def chain_get(buckets, key):
    for stored_key, value in buckets[key % len(buckets)]:
        if stored_key == key:
            return True, value
    return False, None

print(chain_get([[], [(1, "A"), (5, None)], [], []], 5))
print(chain_get([[], [(1, 0)], [], []], 1))
print(chain_get([[], []], 9))

def chain_put(buckets, key, value):
    bucket = buckets[key % len(buckets)]
    for index, (stored_key, _) in enumerate(bucket):
        if stored_key == key:
            bucket[index] = (key, value)
            return False
    bucket.append((key, value))
    return True

for buckets, key, value in [([[], [(1, "A")], [], []], 5, "B"), ([[], [(1, "A"), (5, "B")], [], []], 1, None), ([[], []], 0, 0)]:
    print(chain_put(buckets, key, value), buckets)

def chain_delete(buckets, key):
    bucket = buckets[key % len(buckets)]
    for index, (stored_key, value) in enumerate(bucket):
        if stored_key == key:
            bucket.pop(index)
            return True, value
    return False, None

for buckets, key in [([[], [(1, "A"), (5, "B")], [], []], 1), ([[], [(1, None)], [], []], 1), ([[], []], 3)]:
    print(chain_delete(buckets, key), buckets)

def linear_place(slots, key):
    start = key % len(slots)
    for step in range(len(slots)):
        index = (start + step) % len(slots)
        if slots[index] == key:
            return index
        if slots[index] is None:
            slots[index] = key
            return index
    return None

for slots, key in [([None, None, None, None], 1), ([None, None, None, 3], 7), ([0, 1, 2, 3], 2), ([0, 1, 2, 3], 5)]:
    print(linear_place(slots, key), slots)
